/// How many game ticks an item burns for; `None` when it is not fuel.
pub fn fuel_ticks(item: ItemKind) -> Option<u32> {
    FUEL.binary_search_by_key(&item.id(), |f| f.item.id())
        .ok()
        .and_then(|i| FUEL.get(i))
        .map(|f| f.ticks)
}
